class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __repr__(self):
        return f"Point(x={self.x}, y={self.y})"

    def __str__(self):
        return f"({self.x}, {self.y})"

    def __eq__(self, other):
        return isinstance(other, Point) and (self.x, self.y) == (other.x, other.y)

p = Point(3, 4)
print(p)
print(repr(p))
print([p, Point(0, 0)])
print(p == Point(3, 4), p == Point(4, 3))

class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return "..."

    def introduce(self):
        return f"I am {self.name} and I say {self.speak()}"

class Dog(Animal):
    def speak(self):
        return "Woof"

class Cat(Animal):
    def __init__(self, name, indoor=True):
        super().__init__(name)
        self.indoor = indoor

    def speak(self):
        return "Meow"

for animal in [Dog("Rex"), Cat("Tom", indoor=False), Animal("Thing")]:
    print(animal.introduce())

tom = Cat("Tom")
print(isinstance(tom, Animal), isinstance(tom, Dog), tom.indoor)
